import{_ as o,l,o as e,c as d,v as t,p as s,x as i,d as n,i as E,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"EDF","description":"","frontmatter":{"title":"EDF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/edf-sched.md","filePath":"cs/edf-sched.md","lastUpdated":1789023840000}'),p={name:"cs/edf-sched.md"};function _(h,a,D,m,u,A){const r=l("Mermaid");return e(),d("div",null,[a[1]||(a[1]=t('<h1 id="edf" tabindex="-1">EDF <a class="header-anchor" href="#edf" aria-label="Permalink to &quot;EDF&quot;">​</a></h1><div class="epigraph"><p>总是跑当前绝对截止最早的任务；在同样的经典假设下，利用率不超过 1 则可调度，比速率单调更密。</p><footer>—— 据 Liu and Layland, JACM 1973；Silberschatz et al. 对最早截止优先的整理</footer></div><p><a href="/cs/rate-monotonic">上一课</a>用静态周期指定优先级，利用率界限约 0.69。缺口是<strong>最早截止优先（EDF）</strong>：优先级随绝对截止 \\(d_i\\) 变，谁更紧急谁跑。Liu–Layland 下 \\(\\sum C_i/P_i \\le 1\\) 即充分（且必要，对隐式截止）。本课钉这根动态尺子，不写 CBS 服务器。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RM 可能拒绝一组其实能在单核上排下的任务，只因为静态优先级不够密。EDF 每次调度比较当前绝对截止，抢占发生在更早截止的任务释放时。缺口不是再讲周期任务模型，而是：<strong>动态优先级换来更高利用率，换出入队时重排与过载行为不同</strong>。</p><p><span class="marginnote">过载时 EDF 会让许多任务都稍微逾期；RM 往往让低优先级任务单独炸掉。哪一种更可接受是政策，不是定理。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>释放时计算 \\(d_i =\\) 释放时刻 \\(+ D_i\\)（常 \\(D_i=P_i\\)）。runqueue 按 \\(d_i\\) 排序。调度：队头即最早截止。利用率测试：和 \\(\\le 1\\)。与 RM 一样忽略切换税除非打进 \\(C\\)。多核上全局 EDF 没有单核这么干净的界限，本课只钉单核。</p>',8)),(e(),s(c,null,{default:i(()=>[E(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20REL%5B%22%E4%BB%BB%E5%8A%A1%E9%87%8A%E6%94%BE%22%5D%20--%3E%20D%5B%22%E7%BB%9D%E5%AF%B9%E6%88%AA%E6%AD%A2%22%5D%0A%20%20D%20--%3E%20Q%5B%22%E6%8C%89%E6%88%AA%E6%AD%A2%E6%8E%92%E5%BA%8F%22%5D%0A%20%20Q%20--%3E%20RUN%5B%22%E8%B7%91%E6%9C%80%E6%97%A9%E8%80%85%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>Linux <code>SCHED_DEADLINE</code> 一类是直觉近亲，实现含运行时预算；主干不当成源码课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>EDF 在经典假设下单核最优：能被某算法排下的，EDF 也能。它仍怕锁：反转会让「最早截止」空等。与 vruntime 对照：EDF 最小化逾期，不摊份额；后台编译若误进 EDF 会饿死分时任务，所以调度类要隔离。</p><p>实现成本：每个事件可能对数时间重排，而 RM 是固定槽。这是工程税，不是可调度性。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把多核可调度性的全部反例写完，不引入弱截止的 \\(m\\)-in-\\(k\\)。也不把网络包的 EDF 排队当成 CPU 调度。CPU 绑核如何限制 EDF/RM 的迁移，下一课。</p><p>后课默认：单核期限调度可用 RM 或 EDF。任务与中断还要能钉在某几颗核上，下一课讲 CPU 亲和。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>EDF：跑当前最早绝对截止；单核利用率界限为 1。</li><li>过载形态与 RM 不同；锁仍能破坏期限。</li><li>绑核是下一课。</li><li>出处：Liu and Layland, <em>JACM</em> 1973；Silberschatz et al., <em>OSC</em>。</li></ul>',9))])}const C=o(p,[["render",_]]);export{B as __pageData,C as default};
